#!/bin/sh
# AUTO-GENERATED by plan-writes.sh - reviewed, revertible on-box write script.
# Run on the box only, attended, with the recovery door armed and UART capture running.
#   print plan:  sh apply-W21.sh
#   apply:       LSW_WRITE_ATTENDED=1 LSW_RECOVERY_ARMED=1 sh apply-W21.sh --apply
#   revert:      LSW_WRITE_ATTENDED=1 LSW_RECOVERY_ARMED=1 sh apply-W21.sh --revert
set -u
DEV=""
for c in /usr/bin/devmem /bin/devmem; do [ -x "$c" ] && DEV="$c" && break; done
[ -n "$DEV" ] || DEV=$(command -v devmem 2>/dev/null || true)
RB="${0}.rollback.$(date +%Y%m%dT%H%M%S)"

A1=0x124d4010; V1=0x00000000; R1=0x00000000   # tagact[1].w0
A2=0x124d4014; V2=0x0000c000; R2=0x00000000   # tagact[1].w1 (del-tag action payload)
A3=0x124d4018; V3=0x00000000; R3=0x00000000   # tagact[1].w2
A4=0x124d401c; V4=0x00000000; R4=0x00000000   # tagact[1].w3

set -- "$@"
MODE=""
for arg in "$@"; do
	case "$arg" in
	--apply) MODE=apply ;;
	--revert) MODE=revert ;;
	-h|--help) MODE=help ;;
	*) echo "unknown argument: $arg" >&2; exit 2 ;;
	esac
done
if [ "$MODE" = help ]; then
	echo "print plan (no args) | --apply | --revert; apply/revert need LSW_WRITE_ATTENDED=1 LSW_RECOVERY_ARMED=1"
	exit 0
fi

rd() { "$DEV" "$1" 32 2>/dev/null | tr -d ' \t\r\n'; }

if [ "$MODE" = revert ]; then
	[ -n "$DEV" ] || { echo "no devmem tool" >&2; exit 3; }
	[ "${LSW_WRITE_ATTENDED:-0}" = 1 ] && [ "${LSW_RECOVERY_ARMED:-0}" = 1 ] || {
		echo "refusing: LSW_WRITE_ATTENDED=1 and LSW_RECOVERY_ARMED=1 are required" >&2; exit 5; }
	[ -f "$RB" ] || RB=$(ls -t "$0".rollback.* 2>/dev/null | head -n 1)
	[ -f "$RB" ] || { echo "no rollback file for $0 (expected $RB)" >&2; exit 6; }
	echo "reverting from $RB"
	while read -r a v; do
		[ -n "$a" ] || continue
		echo "devmem $a 32 $v"
		"$DEV" "$a" 32 "$v" || { echo "revert write failed at $a" >&2; exit 7; }
	done <"$RB"
	echo "revert done - re-read the words to confirm"
	exit 0
fi

if [ "$MODE" != apply ]; then
	echo "=== PLAN (no writes performed) ==="
	i=1; while [ "$i" -le 4 ]; do
		eval "a=\$A$i; v=\$V$i; r=\$R$i"
		echo "write 0x$(printf %x "$a") 0x$(printf %x "$v")  rollback 0x$(printf %x "$r")"
		i=$((i + 1)); done
	echo "=== committed to hardware only with --apply and both env flags ==="
	exit 0
fi

[ -n "$DEV" ] || { echo "no devmem tool" >&2; exit 3; }
[ "${LSW_WRITE_ATTENDED:-0}" = 1 ] && [ "${LSW_RECOVERY_ARMED:-0}" = 1 ] || {
	echo "refusing: LSW_WRITE_ATTENDED=1 and LSW_RECOVERY_ARMED=1 are required" >&2; exit 5; }
echo "PRE-FLIGHT: verifying every target word still reads the captured rollback value"
i=1; while [ "$i" -le 4 ]; do
	eval "a=\$A$i; r=\$R$i"
	cur=$(rd "$a")
	cur=$((cur))
	[ $((cur)) -eq $((r)) ] || { echo "target 0x$(printf %x "$a") reads 0x$(printf %x "$cur"), expected rollback 0x$(printf %x "$r"); state changed since capture - aborting" >&2; exit 8; }
	echo "  ok 0x$(printf %x "$a") = 0x$(printf %x "$cur")"
	i=$((i + 1)); done

: >"$RB"
i=1; while [ "$i" -le 4 ]; do
	eval "a=\$A$i"
	cur=$(rd "$a")
	echo "0x$(printf %x "$a") 0x$(printf %x "$((cur))")" >>"$RB"
	i=$((i + 1)); done
echo "rollback file: $RB"

APPLIED=0
revert_partial() {
	j=$APPLIED
	while [ "$j" -ge 1 ]; do
		eval "a=\$A$j; r=\$R$j"
		"$DEV" "$a" 32 "$r" >/dev/null 2>&1 || echo "PARTIAL REVERT FAILED at 0x$(printf %x "$a") - reinstall the canonical image" >&2
		j=$((j - 1))
	done
}
i=1; while [ "$i" -le 4 ]; do
	eval "a=\$A$i; v=\$V$i; r=\$R$i"
	echo "write 0x$(printf %x "$a") <- 0x$(printf %x "$v") (rollback 0x$(printf %x "$r"))"
	if ! "$DEV" "$a" 32 "$v"; then echo "write failed at 0x$(printf %x "$a")" >&2; revert_partial; exit 9; fi
	APPLIED=$i
	got=$(rd "$a"); got=$((got))
	if [ $((got)) -ne $((v)) ]; then
		echo "READBACK MISMATCH at 0x$(printf %x "$a"): wrote 0x$(printf %x "$v"), read 0x$(printf %x "$got") - reverting" >&2
		revert_partial; exit 10
	fi
	echo "  readback ok"
	i=$((i + 1)); done
echo "APPLIED $APPLIED words; rollback file $RB"
echo "validate traffic now (UART/rxdiag); to revert: sh $0 --revert"
exit 0
